-- MOZLYT inventory: schema for Supabase, rebuilt from the Neon database (dry-art-70465054 / mozlyt) on 23 Nov 2026.
-- Same tables, columns, checks, keys, functions and access rules as Neon, with three changes:
--   1. Neon's auth.user_id() becomes Supabase's auth.uid()::text.
--   2. Columns that used a separate nextval() sequence become identity columns (same values are copied in).
--   3. stock_counts.product_id is text with a key to products (it was a number, which no product id could match).
-- Triggers are added in 002 after the data is copied, so copying does not create fake audit rows.

-- ---------- tables ----------
CREATE TABLE public.app_owner (user_id text NOT NULL, email text NOT NULL, added_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.audit_log (id bigint GENERATED ALWAYS AS IDENTITY NOT NULL, table_name text NOT NULL, row_id text, action text NOT NULL, before jsonb, after jsonb, actor text, at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.marketers (id text NOT NULL, no integer NOT NULL, name text NOT NULL, phone text DEFAULT '' NOT NULL, area text DEFAULT '' NOT NULL, active boolean DEFAULT true NOT NULL, joined date DEFAULT CURRENT_DATE NOT NULL, removed_at timestamptz, fresh_from date);
CREATE TABLE public.products (id text NOT NULL, no integer NOT NULL, name text NOT NULL, price numeric(12,2) NOT NULL, active boolean DEFAULT true NOT NULL, cost numeric(12,2) DEFAULT 0 NOT NULL, low_stock integer DEFAULT 5 NOT NULL);
CREATE TABLE public.settings (id integer DEFAULT 1 NOT NULL, target integer DEFAULT 5 NOT NULL, pay numeric(12,2) DEFAULT 0 NOT NULL,
  daily_expenses jsonb DEFAULT '[{"cat": "Transport", "label": "Transport: Adjeman → Amasaman", "amount": 10}, {"cat": "Transport", "label": "Transport: Amasaman → Seku", "amount": 10}, {"cat": "Transport", "label": "Transport back home", "amount": 20}, {"cat": "Transport", "label": "Extra fare (coming late)", "amount": 0}, {"cat": "Food", "label": "Food when out", "amount": 50}, {"cat": "Food", "label": "Food at night", "amount": 20}]'::jsonb NOT NULL,
  record_start date DEFAULT '2026-11-19' NOT NULL);
CREATE TABLE public.locations (id bigint GENERATED ALWAYS AS IDENTITY NOT NULL, name text NOT NULL, active boolean DEFAULT true NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.customers (id bigint GENERATED ALWAYS AS IDENTITY NOT NULL, full_name text NOT NULL, phone text NOT NULL,
  phone_norm text GENERATED ALWAYS AS (CASE WHEN length(regexp_replace(phone, '\D', '', 'g')) = 12 AND regexp_replace(phone, '\D', '', 'g') LIKE '233%' THEN '0' || substr(regexp_replace(phone, '\D', '', 'g'), 4) ELSE regexp_replace(phone, '\D', '', 'g') END) STORED,
  alt_phone text, address text, city text, gps_text text, notes text, location_id bigint, created_at timestamptz DEFAULT now() NOT NULL, created_by text, active boolean DEFAULT true NOT NULL);
CREATE TABLE public.sales (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, day date NOT NULL, marketer_id text NOT NULL, product_id text NOT NULL, product_name text NOT NULL, qty integer NOT NULL, price numeric(12,2) NOT NULL, cost numeric(12,2) DEFAULT 0 NOT NULL, method text DEFAULT 'cash' NOT NULL, note text DEFAULT '' NOT NULL, created_at timestamptz DEFAULT now() NOT NULL, customer text DEFAULT '' NOT NULL, due_date date, paid_at timestamptz, customer_id bigint, recorded_by text, location_id bigint, is_legacy boolean DEFAULT false NOT NULL);
CREATE TABLE public.sales_old (day date NOT NULL, marketer_id text NOT NULL, product_id text NOT NULL, product_name text NOT NULL, qty integer NOT NULL, price numeric(12,2) NOT NULL, updated_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.customer_payments (id bigint GENERATED ALWAYS AS IDENTITY NOT NULL, sale_id bigint NOT NULL, customer_id bigint, amount numeric NOT NULL, method text NOT NULL, paid_at timestamptz DEFAULT now() NOT NULL, day date NOT NULL, held_by text NOT NULL, recorded_by text NOT NULL, note text DEFAULT '' NOT NULL, voided_at timestamptz, voided_by text, void_reason text, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.savings (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, day date NOT NULL, marketer_id text NOT NULL, amount numeric(12,2) NOT NULL, note text DEFAULT '' NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.payments (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, day date NOT NULL, marketer_id text NOT NULL, amount numeric(12,2) NOT NULL, method text DEFAULT 'cash' NOT NULL, note text DEFAULT '' NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.expenses (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, day date NOT NULL, category text DEFAULT 'Other' NOT NULL, amount numeric(12,2) NOT NULL, note text DEFAULT '' NOT NULL, created_at timestamptz DEFAULT now() NOT NULL, ownership text DEFAULT 'business' NOT NULL, seller_id text);
CREATE TABLE public.stock_moves (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, day date NOT NULL, product_id text NOT NULL, kind text NOT NULL, marketer_id text, qty integer NOT NULL, unit_cost numeric(12,2), note text DEFAULT '' NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.stock_funds (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, day date NOT NULL, amount numeric NOT NULL, note text DEFAULT '' NOT NULL, created_at timestamptz DEFAULT now() NOT NULL, kind text DEFAULT 'add' NOT NULL);
CREATE TABLE public.stock_counts (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, day date NOT NULL, product_id text NOT NULL, counted numeric NOT NULL, system_qty numeric NOT NULL, difference numeric NOT NULL, reason text DEFAULT '' NOT NULL, adjust_move_id bigint, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.seller_logins (user_id text NOT NULL, marketer_id text NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.therapists (id text NOT NULL, no integer NOT NULL, name text NOT NULL, phone text DEFAULT '' NOT NULL, monthly_pay numeric DEFAULT 0 NOT NULL, active boolean DEFAULT true NOT NULL, joined date DEFAULT CURRENT_DATE NOT NULL, removed_at timestamptz);
CREATE TABLE public.services (id text NOT NULL, name text NOT NULL, kind text DEFAULT 'single' NOT NULL, price numeric DEFAULT 0 NOT NULL, sessions integer DEFAULT 1 NOT NULL, active boolean DEFAULT true NOT NULL, sort integer DEFAULT 0 NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.kit_items (id text NOT NULL, name text NOT NULL, unit text DEFAULT 'pc' NOT NULL, cost numeric DEFAULT 0 NOT NULL, active boolean DEFAULT true NOT NULL, low_stock integer DEFAULT 5 NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.service_kit (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, service_id text NOT NULL, kit_item_id text NOT NULL, qty numeric DEFAULT 1 NOT NULL);
CREATE TABLE public.bookings (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, day date NOT NULL, service_id text, service_name text DEFAULT '' NOT NULL, kind text DEFAULT 'single' NOT NULL, customer text DEFAULT '' NOT NULL, phone text DEFAULT '' NOT NULL, price numeric DEFAULT 0 NOT NULL, source text DEFAULT 'direct' NOT NULL, therapist_id text, sessions_total integer DEFAULT 1 NOT NULL, sessions_used integer DEFAULT 0 NOT NULL, status text DEFAULT 'open' NOT NULL, note text DEFAULT '' NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.booking_payments (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, day date NOT NULL, booking_id bigint NOT NULL, amount numeric NOT NULL, kind text DEFAULT 'payment' NOT NULL, method text DEFAULT 'cash' NOT NULL, note text DEFAULT '' NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.deliveries (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, day date NOT NULL, booking_id bigint NOT NULL, session_no integer NOT NULL, therapist_id text, note text DEFAULT '' NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.kit_moves (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, day date NOT NULL, kit_item_id text NOT NULL, kind text NOT NULL, qty numeric NOT NULL, unit_cost numeric, booking_id bigint, note text DEFAULT '' NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);
CREATE TABLE public.therapist_pay (id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, day date NOT NULL, therapist_id text NOT NULL, amount numeric NOT NULL, note text DEFAULT '' NOT NULL, created_at timestamptz DEFAULT now() NOT NULL);

