ALTER TABLE public.customer_payments ADD CONSTRAINT customer_payments_pkey PRIMARY KEY (id);
ALTER TABLE public.savings ADD CONSTRAINT savings_pkey PRIMARY KEY (id);
ALTER TABLE public.payments ADD CONSTRAINT payments_pkey PRIMARY KEY (id);
ALTER TABLE public.expenses ADD CONSTRAINT expenses_pkey PRIMARY KEY (id);
ALTER TABLE public.stock_moves ADD CONSTRAINT stock_moves_pkey PRIMARY KEY (id);
ALTER TABLE public.stock_funds ADD CONSTRAINT stock_funds_pkey PRIMARY KEY (id);
ALTER TABLE public.stock_counts ADD CONSTRAINT stock_counts_pkey PRIMARY KEY (id);
ALTER TABLE public.seller_logins ADD CONSTRAINT seller_logins_pkey PRIMARY KEY (user_id);
ALTER TABLE public.therapists ADD CONSTRAINT therapists_pkey PRIMARY KEY (id);
ALTER TABLE public.services ADD CONSTRAINT services_pkey PRIMARY KEY (id);
ALTER TABLE public.kit_items ADD CONSTRAINT kit_items_pkey PRIMARY KEY (id);
ALTER TABLE public.service_kit ADD CONSTRAINT service_kit_pkey PRIMARY KEY (id);
ALTER TABLE public.service_kit ADD CONSTRAINT service_kit_service_id_kit_item_id_key UNIQUE (service_id, kit_item_id);
ALTER TABLE public.bookings ADD CONSTRAINT bookings_pkey PRIMARY KEY (id);
ALTER TABLE public.booking_payments ADD CONSTRAINT booking_payments_pkey PRIMARY KEY (id);
ALTER TABLE public.deliveries ADD CONSTRAINT deliveries_pkey PRIMARY KEY (id);
ALTER TABLE public.deliveries ADD CONSTRAINT deliveries_booking_id_session_no_key UNIQUE (booking_id, session_no);
ALTER TABLE public.kit_moves ADD CONSTRAINT kit_moves_pkey PRIMARY KEY (id);
ALTER TABLE public.therapist_pay ADD CONSTRAINT therapist_pay_pkey PRIMARY KEY (id);

-- ---------- checks ----------
ALTER TABLE public.settings ADD CONSTRAINT settings_id_check CHECK (id = 1);
ALTER TABLE public.customers ADD CONSTRAINT customers_phone_check CHECK (length(regexp_replace(phone, '\D', '', 'g')) >= 9);
ALTER TABLE public.sales ADD CONSTRAINT sales_qty_check1 CHECK (qty > 0);
ALTER TABLE public.sales ADD CONSTRAINT sales_method_check CHECK (method = ANY (ARRAY['cash','momo','credit']));
ALTER TABLE public.sales_old ADD CONSTRAINT sales_qty_check CHECK (qty > 0);
ALTER TABLE public.customer_payments ADD CONSTRAINT customer_payments_method_check CHECK (method = ANY (ARRAY['cash','momo']));
ALTER TABLE public.customer_payments ADD CONSTRAINT customer_payments_check CHECK ((voided_at IS NULL) = (void_reason IS NULL));
ALTER TABLE public.customer_payments ADD CONSTRAINT customer_payments_amount_check CHECK (amount > 0);
ALTER TABLE public.payments ADD CONSTRAINT payments_method_check CHECK (method = ANY (ARRAY['cash','momo']));
ALTER TABLE public.payments ADD CONSTRAINT payments_amount_check CHECK (amount > 0);
ALTER TABLE public.expenses ADD CONSTRAINT expenses_ownership_check CHECK (ownership = ANY (ARRAY['seller','business']));
ALTER TABLE public.expenses ADD CONSTRAINT expenses_amount_check CHECK (amount > 0);
ALTER TABLE public.stock_moves ADD CONSTRAINT stock_moves_qty_check CHECK (qty <> 0);
ALTER TABLE public.stock_moves ADD CONSTRAINT stock_moves_kind_check CHECK (kind = ANY (ARRAY['in','out','return','adjust']));
ALTER TABLE public.stock_moves ADD CONSTRAINT stock_moves_check CHECK ((kind = ANY (ARRAY['out','return'])) = (marketer_id IS NOT NULL));
ALTER TABLE public.stock_moves ADD CONSTRAINT stock_moves_check1 CHECK (kind = 'adjust' OR qty > 0);
ALTER TABLE public.services ADD CONSTRAINT services_kind_check CHECK (kind = ANY (ARRAY['single','plan']));
ALTER TABLE public.services ADD CONSTRAINT services_sessions_check CHECK (sessions >= 1);
ALTER TABLE public.service_kit ADD CONSTRAINT service_kit_qty_check CHECK (qty > 0);
ALTER TABLE public.bookings ADD CONSTRAINT bookings_source_check CHECK (source = ANY (ARRAY['platform','direct','personal']));
ALTER TABLE public.bookings ADD CONSTRAINT bookings_status_check CHECK (status = ANY (ARRAY['open','done','cancelled']));
ALTER TABLE public.bookings ADD CONSTRAINT bookings_kind_check CHECK (kind = ANY (ARRAY['single','plan']));
ALTER TABLE public.booking_payments ADD CONSTRAINT booking_payments_amount_check CHECK (amount > 0);
ALTER TABLE public.booking_payments ADD CONSTRAINT booking_payments_kind_check CHECK (kind = ANY (ARRAY['deposit','payment']));
ALTER TABLE public.kit_moves ADD CONSTRAINT kit_moves_kind_check CHECK (kind = ANY (ARRAY['in','issue','adjust']));
ALTER TABLE public.therapist_pay ADD CONSTRAINT therapist_pay_amount_check CHECK (amount > 0);

