ALTER TABLE public.sales_old ADD CONSTRAINT sales_marketer_id_fkey FOREIGN KEY (marketer_id) REFERENCES public.marketers(id);
ALTER TABLE public.customer_payments ADD CONSTRAINT customer_payments_sale_id_fkey FOREIGN KEY (sale_id) REFERENCES public.sales(id);
