CREATE INDEX savings_marketer ON public.savings (marketer_id);

-- ---------- functions ----------
CREATE OR REPLACE FUNCTION public.is_owner() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public', 'pg_temp'
AS $f$ SELECT auth.uid() IS NOT NULL AND EXISTS (SELECT 1 FROM public.app_owner WHERE user_id = auth.uid()::text) $f$;

CREATE OR REPLACE FUNCTION public.my_seller_id() RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public', 'pg_temp'
AS $f$ SELECT marketer_id FROM public.seller_logins WHERE user_id = auth.uid()::text $f$;

CREATE OR REPLACE FUNCTION public.audit_row() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public', 'pg_temp'
AS $f$ DECLARE actor text; BEGIN actor := coalesce(auth.uid()::text, current_user);
 IF TG_OP = 'INSERT' THEN INSERT INTO public.audit_log (table_name, row_id, action, before, after, actor) VALUES (TG_TABLE_NAME, NEW.id::text, 'insert', NULL, to_jsonb(NEW), actor);
 ELSIF TG_OP = 'UPDATE' THEN INSERT INTO public.audit_log (table_name, row_id, action, before, after, actor) VALUES (TG_TABLE_NAME, NEW.id::text, 'update', to_jsonb(OLD), to_jsonb(NEW), actor);
 ELSE INSERT INTO public.audit_log (table_name, row_id, action, before, after, actor) VALUES (TG_TABLE_NAME, OLD.id::text, 'delete', to_jsonb(OLD), NULL, actor); END IF;
 RETURN NULL; END $f$;

CREATE OR REPLACE FUNCTION public.customer_payment_check() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public', 'pg_temp'
AS $f$ DECLARE tot numeric; m text; paid numeric; BEGIN
 IF NEW.voided_at IS NULL THEN
  PERFORM 1 FROM public.sales WHERE id = NEW.sale_id FOR UPDATE;
  SELECT qty * price, method INTO tot, m FROM public.sales WHERE id = NEW.sale_id;
  IF tot IS NULL THEN RAISE EXCEPTION 'sale % not found', NEW.sale_id; END IF;
  IF m IS DISTINCT FROM 'credit' THEN RAISE EXCEPTION 'payments can only be recorded against a credit sale'; END IF;
  SELECT coalesce(sum(amount), 0) INTO paid FROM public.customer_payments WHERE sale_id = NEW.sale_id AND voided_at IS NULL;
  IF paid + NEW.amount > tot THEN RAISE EXCEPTION 'payment of % is more than the outstanding balance of %', NEW.amount, tot - paid; END IF;
 END IF; RETURN NEW; END $f$;

CREATE OR REPLACE FUNCTION public.customer_payment_guard() RETURNS trigger LANGUAGE plpgsql SET search_path TO 'public', 'pg_temp'
AS $f$ BEGIN
 IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'customer payments cannot be deleted; void them instead'; END IF;
 IF OLD.voided_at IS NOT NULL THEN RAISE EXCEPTION 'a voided payment cannot be changed'; END IF;
 IF NEW.voided_at IS NULL THEN RAISE EXCEPTION 'a payment can only be voided, not changed'; END IF;
 IF (NEW.sale_id, NEW.customer_id, NEW.amount, NEW.method, NEW.paid_at, NEW.day, NEW.held_by, NEW.recorded_by, NEW.note, NEW.created_at)
    IS DISTINCT FROM (OLD.sale_id, OLD.customer_id, OLD.amount, OLD.method, OLD.paid_at, OLD.day, OLD.held_by, OLD.recorded_by, OLD.note, OLD.created_at)
 THEN RAISE EXCEPTION 'only the void fields may change on a payment'; END IF;
 RETURN NEW; END $f$;

CREATE OR REPLACE FUNCTION public.get_state(months text[]) RETURNS json LANGUAGE sql STABLE SET search_path TO 'public', 'pg_temp'
AS $f$ SELECT json_build_object('owner', public.is_owner(),
 'marketers',(SELECT coalesce(json_agg(m ORDER BY no),'[]') FROM marketers m),
 'products',(SELECT coalesce(json_agg(p ORDER BY no),'[]') FROM products p),
 'settings',(SELECT row_to_json(s) FROM settings s WHERE id=1),
 'sales',(SELECT coalesce(json_agg(x ORDER BY created_at),'[]') FROM sales x WHERE to_char(day,'YYYY-MM') = ANY(months)),
 'credit',(SELECT coalesce(json_agg(c ORDER BY due_date NULLS LAST, created_at),'[]') FROM sales c WHERE method='credit'),
 'savings',(SELECT coalesce(json_agg(v ORDER BY created_at),'[]') FROM savings v WHERE to_char(day,'YYYY-MM') = ANY(months)),
 'payments',(SELECT coalesce(json_agg(y ORDER BY created_at),'[]') FROM payments y WHERE to_char(day,'YYYY-MM') = ANY(months)),
 'expenses',(SELECT coalesce(json_agg(e ORDER BY created_at),'[]') FROM expenses e WHERE to_char(day,'YYYY-MM') = ANY(months)),
 'moves',(SELECT coalesce(json_agg(z ORDER BY created_at DESC),'[]') FROM (SELECT * FROM stock_moves WHERE to_char(day,'YYYY-MM') = ANY(months) UNION SELECT * FROM (SELECT * FROM stock_moves ORDER BY created_at DESC LIMIT 60) l) z),
 'customers',(SELECT coalesce(json_agg(c2 ORDER BY id),'[]') FROM customers c2),
 'customer_payments',(SELECT coalesce(json_agg(k ORDER BY paid_at),'[]') FROM customer_payments k),
 'locations',(SELECT coalesce(json_agg(l ORDER BY id),'[]') FROM locations l)) $f$;

REVOKE EXECUTE ON FUNCTION public.get_state(text[]) FROM anon, public;
GRANT EXECUTE ON FUNCTION public.get_state(text[]) TO authenticated;

-- ---------- row-level security (same rules as Neon) ----------
DO $$ DECLARE t text; BEGIN
 FOREACH t IN ARRAY ARRAY['app_owner','audit_log','marketers','products','settings','locations','customers','sales','sales_old','customer_payments','savings','payments','expenses','stock_moves','stock_funds','stock_counts','seller_logins','therapists','services','kit_items','service_kit','bookings','booking_payments','deliveries','kit_moves','therapist_pay'] LOOP
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', t);
  EXECUTE format('REVOKE ALL ON public.%I FROM anon', t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['marketers','products','settings','locations','customers','sales','sales_old','customer_payments','savings','payments','expenses','stock_moves','stock_funds','stock_counts','seller_logins','therapists','services','kit_items','service_kit','bookings','booking_payments','deliveries','kit_moves','therapist_pay'] LOOP
  EXECUTE format('CREATE POLICY owner_all ON public.%I FOR ALL TO authenticated USING (public.is_owner()) WITH CHECK (public.is_owner())', t);
 END LOOP;
END $$;
-- app_owner: no policy, so no client can read or change who the owner is.
REVOKE ALL ON public.app_owner FROM authenticated;
CREATE POLICY owner_read ON public.audit_log FOR SELECT TO authenticated USING (public.is_owner());
REVOKE INSERT, UPDATE, DELETE ON public.audit_log FROM authenticated;
CREATE POLICY seller_read ON public.locations FOR SELECT TO authenticated USING (public.my_seller_id() IS NOT NULL);
CREATE POLICY seller_read ON public.customers FOR SELECT TO authenticated USING (public.my_seller_id() IS NOT NULL);
CREATE POLICY seller_insert ON public.customers FOR INSERT TO authenticated WITH CHECK (public.my_seller_id() IS NOT NULL);
CREATE POLICY seller_read ON public.customer_payments FOR SELECT TO authenticated USING (public.my_seller_id() IS NOT NULL AND (held_by = public.my_seller_id() OR EXISTS (SELECT 1 FROM public.sales s WHERE s.id = customer_payments.sale_id AND s.marketer_id = public.my_seller_id())));
CREATE POLICY seller_insert ON public.customer_payments FOR INSERT TO authenticated WITH CHECK (held_by = public.my_seller_id() AND voided_at IS NULL AND EXISTS (SELECT 1 FROM public.sales s WHERE s.id = customer_payments.sale_id AND s.marketer_id = public.my_seller_id() AND s.method = 'credit'));
